#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Triage {
    Route(FindingRoute),
    Backlog,
    Drop(FindingDrop),
    Repair(FindingRepair),
    Blame(FindingBlameAct),
}

// Record: Triage.
impl Triage {
    const SHAPE: &'static [skein_codec::bounds::Node] = &[
        skein_codec::bounds::Node::Named("FindingRoute"),
        skein_codec::bounds::Node::Scalar(0),
        skein_codec::bounds::Node::Named("FindingDrop"),
        skein_codec::bounds::Node::Named("FindingRepair"),
        skein_codec::bounds::Node::Named("FindingBlameAct"),
        skein_codec::bounds::Node::Enum { variants: &[0, 1, 2, 3, 4] },
    ];

    /// The record's encoded bound with every limit it reaches set to zero.
    pub const ENCODED_AT_ZERO: u64 = 10;
}

impl Record for Triage {
    type Limits = Limits;
    const TAIL: Path = paths::TRIAGE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "Triage")?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "Triage")?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Route(value) => { field::put(out, &[0], paths::TRIAGE_TAG)?; value.write(limits, out) },
            Self::Backlog => field::put(out, &[1], paths::TRIAGE_TAG),
            Self::Drop(value) => { field::put(out, &[2], paths::TRIAGE_TAG)?; value.write(limits, out) },
            Self::Repair(value) => { field::put(out, &[3], paths::TRIAGE_TAG)?; value.write(limits, out) },
            Self::Blame(value) => { field::put(out, &[4], paths::TRIAGE_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::TRIAGE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Route(FindingRoute::read(limits, reader)?)),
            1 => Ok(Self::Backlog),
            2 => Ok(Self::Drop(FindingDrop::read(limits, reader)?)),
            3 => Ok(Self::Repair(FindingRepair::read(limits, reader)?)),
            4 => Ok(Self::Blame(FindingBlameAct::read(limits, reader)?)),
            5..=u8::MAX => Err(Problem { path: paths::TRIAGE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

